CommitDate: Wed Jan 14 21:40:29 2026 +1300

    Bug 2010213 - Fix attachments to open on double-click and enter only. r=mkmelin
    Bug 2009644 made richlistbox fire a bunch more "command" events, at times when we do not want to
    open the selected attachments. This patch changes what events we listen for.

    Differential Revision: https://phabricator.services.mozilla.com/D278938

diff --git a/mail/base/content/aboutMessage.js b/mail/base/content/aboutMessage.js
index 7c8a6c3cd25..2e3d5cbfd47 100644
--- a/mail/base/content/aboutMessage.js
+++ b/mail/base/content/aboutMessage.js
@@ -10,9 +10,10 @@
 /* globals gDBView: true, gFolder: true, gViewWrapper: true */

 // msgHdrView.js
-/* globals AdjustHeaderView ClearCurrentHeaders ClearPendingReadTimer
-   HideMessageHeaderPane initFolderDBListener OnLoadMsgHeaderPane OnTagsChange
-   OnUnloadMsgHeaderPane HandleAllAttachments AttachmentMenuController */
+/* globals AdjustHeaderView AttachmentMenuController ClearCurrentHeaders
+     ClearPendingReadTimer HandleAllAttachments HandleSelectedAttachments
+     HideMessageHeaderPane initFolderDBListener OnLoadMsgHeaderPane
+     OnTagsChange OnUnloadMsgHeaderPane */

 var { MailServices } = ChromeUtils.importESModule(
   "resource:///modules/MailServices.sys.mjs"
@@ -753,6 +754,12 @@ commandController.registerCallback("cmd_fullZoomToggle", () => {
 });

 // Attachments commands.
+commandController.registerCallback(
+  "cmd_openAttachment",
+  () => HandleSelectedAttachments("open"),
+  () => AttachmentMenuController.someFilesAvailable()
+);
+
 commandController.registerCallback(
   "cmd_openAllAttachments",
   () => HandleAllAttachments("open"),
diff --git a/mail/base/content/aboutMessage.xhtml b/mail/base/content/aboutMessage.xhtml
index 7b05b038823..fc192bc0fae 100644
--- a/mail/base/content/aboutMessage.xhtml
+++ b/mail/base/content/aboutMessage.xhtml
@@ -88,6 +88,8 @@
   <stringbundle id="bundle_messenger" src="chrome://messenger/locale/messenger.properties"/>

   <commandset id="attachmentCommands">
+    <command id="cmd_openAttachment"
+             oncommand="goDoCommand('cmd_openAttachment');"/>
     <command id="cmd_openAllAttachments"
              oncommand="goDoCommand('cmd_openAllAttachments');"/>
     <command id="cmd_saveAllAttachments"
diff --git a/mail/base/content/msgHdrView.js b/mail/base/content/msgHdrView.js
index bf2e9bea74b..3d8f09a7e5b 100644
--- a/mail/base/content/msgHdrView.js
+++ b/mail/base/content/msgHdrView.js
@@ -1802,16 +1802,6 @@ function onShowSaveAttachmentMenuMultiple() {
   deleteAllItem.disabled = !canDetach || !allAllowedURL;
 }

-/**
- * This is our oncommand handler for the attachment list items. A double click
- * or enter press in an attachmentitem simulates "opening" the attachment.
- *
- * @param {Event} _event - The event.
- */
-function attachmentItemCommand(_event) {
-  HandleSelectedAttachments("open");
-}
-
 var AttachmentListController = {
   supportsCommand(command) {
     switch (command) {
@@ -1919,7 +1909,6 @@ async function displayAttachmentsForExpandedView() {
       var displayName = SanitizeAttachmentDisplayName(attachment);
       var item = attachmentList.appendItem(attachment, displayName);
       item.setAttribute("tooltiptext", attachment.name);
-      item.addEventListener("command", attachmentItemCommand);

       // Get a detached file's size. For link attachments, the user must always
       // initiate the fetch for privacy reasons.
